const body = $input.first().json.body || {};
const mode = ['non_users','volunteers'].includes(body.mode) ? body.mode : 'n8n_users';
const extra = body.filters && typeof body.filters === 'object' ? body.filters : {};
const rawClauses = Array.isArray(body.rawClauses) ? body.rawClauses : [];
function withExtra(base) {
  for (const [k, v] of Object.entries(extra)) {
    if (Array.isArray(v)) base.push({ or: v.map(x => ({ attribute: { field: k, operator: 'eq', value: String(x) } })) });
    else if (v !== null && v !== undefined && v !== '') base.push({ attribute: { field: k, operator: 'eq', value: String(v) } });
  }
  for (const c of rawClauses) base.push(c);
  return base;
}
if (mode === 'volunteers') {
  const base = withExtra([
    { attribute: { field: 'email', operator: 'exists' } },
    { attribute: { field: 'origin', operator: 'eq', value: 'user_research_webform' } }
  ]);
  return [{ json: { mode, paginated: true, sampleTarget: Number(body.sample) || 400, cioFilter: { filter: { and: base } } } }];
}
const shards = Number(body.shards) || 40;
const used = new Set();
while (used.size < shards) used.add(Math.floor(Math.random() * 4096));
const base = mode === 'n8n_users' ? [
  { attribute: { field: 'email', operator: 'exists' } },
  { not: { attribute: { field: 'unsubscribed', operator: 'eq', value: 'true' } } },
  { attribute: { field: 'created_n8n_account', operator: 'eq', value: 'true' } },
  { attribute: { field: 'confirmed', operator: 'eq', value: 'true' } }
] : [
  { attribute: { field: 'email', operator: 'exists' } },
  { attribute: { field: 'origin', operator: 'eq', value: 'user_research_webform' } },
  { not: { attribute: { field: 'created_n8n_account', operator: 'eq', value: 'true' } } }
];
withExtra(base);
return Array.from(used).map(sh => ({ json: { mode, paginated: false, shard: sh, sampleTarget: Number(body.sample) || 200, cioFilter: { filter: { and: base.concat([{ attribute: { field: 'uxr_shard', operator: 'eq', value: String(sh) } }]) } } } }));

const q = $('Build Shard Queries').all().map(i => i.json);
const pages = $input.all().map(i => i.json);
let errors = 0, rows = [], perShard = [];
pages.forEach((p, idx) => {
  const status = p.statusCode || 0;
  if (status >= 400) { errors++; return; }
  const ids = (p.body && p.body.identifiers) || [];
  perShard.push(ids.length);
  rows = rows.concat(ids.map(r => ({ cio_id: r.cio_id, id: r.id, email: r.email })));
});
// dedupe (paginated mode may repeat none, but be safe)
const seen = new Set(); rows = rows.filter(r => { if (seen.has(r.cio_id)) return false; seen.add(r.cio_id); return true; });
for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
const target = (q[0] && q[0].sampleTarget) || 200;
const sample = rows.slice(0, target);
const meta = { mode: q[0] && q[0].mode, paginated: !!(q[0] && q[0].paginated), queries: q.length, pagesOrShards: pages.length, queryErrors: errors, collected: rows.length, perPageMin: perShard.length ? Math.min(...perShard) : 0, perPageMax: perShard.length ? Math.max(...perShard) : 0, sampled: sample.length };
if (sample.length === 0) return [{ json: { __empty: true, meta } }];
return sample.map(r => ({ json: { ...r, meta } }));

const samples = $('Collect & Sample').all().map(i => i.json);
const meta = (samples[0] && samples[0].meta) || {};
const fetched = $input.all().map(i => i.json);
const fields = ['cloud_plan','cloud_plan_status','job_role','utm_user_role','company_size','country','timezone','tech_skills_count','marketing_consent','instance_last_seen_at','wf_bucket','services_bucket','ai_wfs_bucket','days_bucket','successful_prod_exec_workflows','services_count','ai_active_wfs','sync_from_big_query','first_name','n8n_usage','tech_skills','last_user_research_invite_date','uxr_shard','unsubscribed','origin'];
const present = {}; fields.forEach(f => present[f] = 0);
const values = { cloud_plan: {}, cloud_plan_status: {}, job_role: {}, utm_user_role: {}, company_size: {}, country: {}, timezone: {}, tech_skills_count: {}, origin: {}, n8n_usage: {}, tech_skills: {} };
let ok = 0, notFound = 0;
for (const r of fetched) {
  const a = r && r.customer && r.customer.attributes;
  if (!a) { notFound++; continue; }
  ok++;
  for (const f of fields) { const v = a[f]; if (v !== undefined && v !== null && String(v).trim() !== '') present[f]++; }
  for (const f of Object.keys(values)) { const v = a[f]; if (v !== undefined && v !== null && String(v) !== '') { const k = String(v).slice(0, 40); values[f][k] = (values[f][k] || 0) + 1; } }
}
const pct = {}; for (const f of fields) pct[f] = ok ? Math.round(100 * present[f] / ok) : null;
const top = {}; for (const f of Object.keys(values)) top[f] = Object.entries(values[f]).sort((a,b)=>b[1]-a[1]).slice(0, 30).map(([k,v]) => k + ': ' + v);
return [{ json: { meta, profilesWithAttributes: ok, notFound, coveragePct: pct, topValues: top } }];
